proc literal {} {expr {7 << 1}}
proc parameter {x} {expr {$x * 2}}
proc eliminated {} {if {0} {expr {7 << 1}}}
foreach command {literal parameter eliminated} {puts "BEGIN $command"; puts [tcl::unsupported::disassemble proc $command]; puts "END $command"}

